const report = $input.first().json.body || $input.first().json;
if (report?.schemaVersion !== 1 || report?.source !== 'abu-oci') throw new Error('Invalid Abu report');
const asText = (value, fallback = 'unavailable') => String(value || fallback).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').slice(0, 500);
const gitleaks = report.gitleaks || {};
const trivy = report.trivy || {};
const severity = gitleaks.findings > 0 || trivy.critical > 0 ? 'HIGH' : trivy.high > 0 ? 'MEDIUM' : 'INFO';
const text = [
  'Abu weekly security report',
  'Severity: ' + severity,
  'Host: ' + asText(report.hostname),
  'Generated: ' + asText(report.generatedAt),
  'Disk use: ' + asText(report.diskUse),
  'Open TCP ports: ' + asText(report.openPorts),
  'Containers: ' + asText(report.containers),
  'n8n executions: ' + asText(report.n8nExecutions),
  'Firewall: ' + asText(report.firewall),
  'Gitleaks: ' + asText(gitleaks.status) + ', findings: ' + Number(gitleaks.findings || 0),
  'Trivy: ' + asText(trivy.status) + ', critical: ' + Number(trivy.critical || 0) + ', high: ' + Number(trivy.high || 0)
].join('\n');
return [{json:{chatId:'YOUR_TELEGRAM_CHAT_ID',text,severity}}];
